// Outdoor path graph. No invented connectors, indoor links or street shortcuts.
(function(root){
const R=6371000,rad=d=>d*Math.PI/180;
function distance(a,b){const y=rad(b[1]-a[1]),x=rad(b[0]-a[0]);return 2*R*Math.asin(Math.sqrt(Math.sin(y/2)**2+Math.cos(rad(a[1]))*Math.cos(rad(b[1]))*Math.sin(x/2)**2))}
function bearing(a,b){const y=Math.sin(rad(b[0]-a[0]))*Math.cos(rad(b[1]));const x=Math.cos(rad(a[1]))*Math.sin(rad(b[1]))-Math.sin(rad(a[1]))*Math.cos(rad(b[1]))*Math.cos(rad(b[0]-a[0]));return (Math.atan2(y,x)*180/Math.PI+360)%360}
function inside(p,ring){let c=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])c=!c}return c}
function segmentDistance(p,a,b){const k=Math.cos(rad(p[1])),ax=(a[0]-p[0])*k,ay=a[1]-p[1],bx=(b[0]-p[0])*k,by=b[1]-p[1],dx=bx-ax,dy=by-ay,t=Math.max(0,Math.min(1,-(ax*dx+ay*dy)/(dx*dx+dy*dy||1)));return Math.hypot(ax+dx*t,ay+dy*t)*111320}
function crosses(a,b,c,d){const ax=b[0]-a[0],ay=b[1]-a[1],bx=d[0]-c[0],by=d[1]-c[1],den=ax*by-ay*bx;if(Math.abs(den)<1e-16)return false;const t=((c[0]-a[0])*by-(c[1]-a[1])*bx)/den,u=((c[0]-a[0])*ay-(c[1]-a[1])*ax)/den;return t>1e-6&&t<.999999&&u>1e-6&&u<.999999}
function build(data){const nodes=new Map();const key=p=>p.map(v=>v.toFixed(7)).join(',');const buildings=data.filter(f=>f.tags.building);for(const f of data){const t=f.tags;if(!(['footway','pedestrian','path','steps'].includes(t.highway)||(t.highway==='cycleway'&&['yes','designated','permissive'].includes(t.foot))))continue;if(['private','no'].includes(t.access)||['private','no'].includes(t.foot)||t.highway==='steps')continue;for(let i=1;i<f.points.length;i++){const a=f.points[i-1],b=f.points[i],d=distance(a,b);if(d<.1)continue;const mid=[(a[0]+b[0])/2,(a[1]+b[1])/2];if(buildings.some(f=>inside(mid,f.points)||f.points.slice(1).some((v,k)=>crosses(a,b,f.points[k],v))))continue;const x=key(a),y=key(b);if(!nodes.has(x))nodes.set(x,{id:x,p:a,edges:[]});if(!nodes.has(y))nodes.set(y,{id:y,p:b,edges:[]});nodes.get(x).edges.push({to:y,d});nodes.get(y).edges.push({to:x,d})}}
let component=0;for(const n of nodes.values()){if(n.component!==undefined)continue;const stack=[n];n.component=component;while(stack.length){const q=stack.pop();for(const e of q.edges){const next=nodes.get(e.to);if(next.component===undefined){next.component=component;stack.push(next)}}}component++}return {nodes,components:component}}
function candidates(graph,endpoint){const ring=endpoint.ring;const out=[];for(const n of graph.nodes.values()){if(ring&&inside(n.p,ring))continue;let d=ring?Infinity:distance(n.p,endpoint.point);if(ring)for(let i=1;i<ring.length;i++)d=Math.min(d,segmentDistance(n.p,ring[i-1],ring[i]));if(d<=(endpoint.maxSnap||70))out.push({n,d})}return out.sort((a,b)=>a.d-b.d).slice(0,40)}
function shortest(graph,start,end){const ds=new Map([[start,0]]),prev=new Map(),open=new Set([start]);while(open.size){let cur=null,min=Infinity;for(const id of open)if(ds.get(id)<min){min=ds.get(id);cur=id}if(cur===end){const ids=[];while(cur){ids.push(cur);cur=prev.get(cur)}return ids.reverse()}open.delete(cur);for(const e of graph.nodes.get(cur).edges){const d=min+e.d;if(d<(ds.get(e.to)??Infinity)){ds.set(e.to,d);prev.set(e.to,cur);open.add(e.to)}}}return null}
function routeSingle(graph,endpoints){const sets=endpoints.map(e=>candidates(graph,e));if(sets.some(s=>!s.length))throw Error('No mapped pedestrian path is close enough to one of these locations. Choose another starting point or building.');const common=[...new Set(sets[0].map(s=>s.n.component))].filter(c=>sets.every(s=>s.some(v=>v.n.component===c)));if(!common.length)throw Error('These locations are not connected in our mapped outdoor paths. We need to verify the missing link before providing directions.');let choice=null;for(const c of common){const snapped=sets.map(s=>s.find(v=>v.n.component===c)),cost=snapped.reduce((a,v)=>a+v.d,0);if(!choice||cost<choice.cost)choice={snapped,cost}}const coords=[];for(let i=1;i<choice.snapped.length;i++){const ids=shortest(graph,choice.snapped[i-1].n.id,choice.snapped[i].n.id);if(!ids)throw Error('A continuous mapped route could not be found.');coords.push(...ids.slice(i===1?0:1).map(id=>graph.nodes.get(id).p))}if(coords.length<2)throw Error('Both locations use the same nearby path point. A distinct outdoor route cannot be determined.');let length=0;const cumulative=[0];for(let i=1;i<coords.length;i++){length+=distance(coords[i-1],coords[i]);cumulative.push(length)}return {coords,length,cumulative,snaps:choice.snapped.map(v=>v.d)}}
// Compare explicitly mapped entrance options by total walking distance, not boundary proximity.
function route(graph,endpoints){let combinations=[[]];for(const endpoint of endpoints){const options=endpoint.alternatives||[endpoint];combinations=combinations.flatMap(prefix=>options.map(option=>[...prefix,option]))}let best=null,lastError;for(const choices of combinations){try{const result=routeSingle(graph,choices),cost=result.length+result.snaps.reduce((sum,d)=>sum+d,0);if(!best||cost<best.cost)best={...result,cost,endpointChoices:choices}}catch(error){lastError=error}}if(!best)throw lastError||Error('No connected mapped entrance was found.');return best}
root.CampusRouting={build,route,distance,bearing,inside};
})(typeof window==='undefined'?globalThis:window);

